 const reconciliationPost=async(body)=>{const r=await fetch('/api/finance-reconciliation-actions',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error({finance_reconciliation_invalid:'Revise a conciliação selecionada.',finance_reconciliation_classification_invalid:'Classificação inválida.'}[j.error]||'Não foi possível salvar a conciliação.');return j;};
 const recoveryPost=async(body)=>{const r=await fetch('/api/finance-recovery-actions',{method:'POST',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json().catch(()=>({}));if(!r.ok){const err=new Error({finance_recovery_promise_required:'Informe data e valor da promessa.',finance_recovery_followup_required:'Informe a próxima data de acompanhamento.',finance_recovery_not_active:'Esta cobrança não está mais ativa para recuperação.',finance_recovery_payment_invalid:'Selecione pelo menos uma ação.'}[j.error]||'Não foi possível salvar o acompanhamento.');throw err;}return j;};
