 function pager(r){return `<footer class="fv1-pagination"><span>${r.total?`${(r.page-1)*r.page_size+1}–${Math.min(r.page*r.page_size,r.total)} de ${r.total.toLocaleString('pt-BR')}`:'0 registros'}</span><div><button type="button" data-fv1-page="${r.page-1}" ${r.page<=1?'disabled':''} aria-label="Página anterior">←</button><span>Página ${r.page} de ${r.pages}</span><button type="button" data-fv1-page="${r.page+1}" ${r.page>=r.pages?'disabled':''} aria-label="Próxima página">→</button></div></footer>`;}
