 function spaceSummary(r){return (r.space_students||[]).map(s=>`<div class="fv1-space-summary">${s.unavailable?'Dados Space indisponíveis':`${e(s.lifecycle_label||'Ciclo não informado')} · ${e(s.student_status||'Status não informado')}${s.plans?.length?' · '+e(s.plans.join(', ')):''}${s.notice?.length?' · Aviso até '+s.notice.map(n=>date(n.last_active_date)).join(', '):''}${s.cs_owner?' · CS: '+e(s.cs_owner):''}`}</div>`).join('');}
