 function receivableRows(rows){return rows.map(r=>`<tr data-fv1-open="${e(r.id)}"><td>${person(r)}${spaceSummary(r)}</td><td>${badge(r)}</td><td class="fv1-number">${money(r.value)}</td><td>${date(r.due_date)}</td><td>${r.days_overdue?`<span class="fv1-late">${r.days_overdue} dias</span>`:'—'}</td><td>${e(r.method_label)}</td><td>${r.subscription_id?`<span class="fv1-id" title="${e(r.subscription_id)}">${e(r.subscription_id)}</span>`:'—'}</td><td><button type="button" class="fv1-row-action" data-fv1-open="${e(r.id)}" aria-label="Ver cobrança ${e(r.id)}">↗</button></td></tr>`).join('');}
