 const history=(r.revenue_history||[]).map(x=>({...x,chart_value:x.current&&x.projected!=null?x.projected:x.revenue})).filter(x=>x.month&&x.chart_value!=null),max=Math.max(1,...history.map(x=>x.chart_value||0)),min=Math.min(...history.map(x=>x.chart_value||0),0),w=760,h=260,pad=34,plotW=w-pad*2,plotH=h-pad*2,pt=(x,i)=>{const xx=pad+(history.length<=1?plotW/2:i*plotW/(history.length-1)),yy=pad+(max===min?plotH/2:(max-(x.chart_value||0))/(max-min)*plotH);return {x:xx,y:yy}},pts=history.map(pt),closedPts=pts.slice(0,Math.max(1,history.findIndex(x=>x.current)>=0?history.findIndex(x=>x.current)+1:pts.length)),line=arr=>arr.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' '),currentIndex=history.findIndex(x=>x.current),currentPt=currentIndex>=0?pts[currentIndex]:null,prevPt=currentIndex>0?pts[currentIndex-1]:null,area=closedPts.length?`${line(closedPts)} L ${closedPts.at(-1).x.toFixed(1)} ${h-pad} L ${closedPts[0].x.toFixed(1)} ${h-pad} Z`:'';
 const chart=history.length?`<section class="fv1-card fv1-exec-chart"><header><div><span class="fv1-section-kicker">Histórico de faturamento</span><h2>Evolução mensal</h2></div><strong>${money(fc.projection??k.revenue)}</strong><small>Mês atual exibido pela projeção</small></header><div class="fv1-line-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Histórico de faturamento mensal"><defs><linearGradient id="fv1RevenueArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#ff7c74" stop-opacity=".30"/><stop offset="1" stop-color="#ff7c74" stop-opacity="0"/></linearGradient></defs><g class="grid"><line x1="${pad}" y1="${pad}" x2="${w-pad}" y2="${pad}"/><line x1="${pad}" y1="${h/2}" x2="${w-pad}" y2="${h/2}"/><line x1="${pad}" y1="${h-pad}" x2="${w-pad}" y2="${h-pad}"/></g>${area?`<path class="area" d="${area}"></path>`:''}<path class="line" d="${line(closedPts)}"></path>${prevPt&&currentPt?`<path class="projection" d="M${prevPt.x.toFixed(1)} ${prevPt.y.toFixed(1)} L${currentPt.x.toFixed(1)} ${currentPt.y.toFixed(1)}"></path>`:''}${history.map((x,i)=>`<g class="point ${x.current?'is-current':''}" tabindex="0"><circle cx="${pts[i].x.toFixed(1)}" cy="${pts[i].y.toFixed(1)}" r="${x.current?6:4}"></circle><title>${fmtMonth(x.month)} · ${x.current?'Projeção ':'Faturamento '}${money(x.chart_value)}</title></g>`).join('')}<g class="labels">${history.map((x,i)=>i%Math.ceil(history.length/6)===0||x.current?`<text x="${pts[i].x.toFixed(1)}" y="${h-8}" text-anchor="middle">${fmtMonth(x.month)}</text>`:'').join('')}<text x="${pad}" y="18">${shortMoney(max)}</text><text x="${pad}" y="${h-pad+18}">${shortMoney(min)}</text></g></svg></div></section>`:'';
