 const recoveryCurve=Object.entries(fc.recovery_curve||{}),health=[['Vencido da competência',money(k.overdue),'alert'],['Recuperação até fechamento',money(fc.expected_recovery_current_month),'ok'],['Recuperação M+15',money(fc.expected_recovery_m15),'ok'],['D+90 estrutural',percent(fc.structural_d90?.rate),'neutral']];
 let html=`<section class="fv1-executive-shell"><div class="fv1-hero-card"><span class="fv1-section-kicker">Faturamento do mês</span><strong>${money(k.revenue)}</strong><p>Recebido ${money(k.received)} • Confirmado ${money(k.confirmed_only)}</p><div><span>Ledger canônico</span><span>${Number(r.meta.revenue_payments||0).toLocaleString('pt-BR')} pagamentos</span></div></div><div class="fv1-side-stack"><article><span>Projeção do mês</span><strong>${money(fc.projection)}</strong><small>Realizado ${money(fc.realized)} • A realizar ${money(delta)}</small></article><article><span>A receber no mês</span><strong>${money(k.due)}</strong><small>Base de cobranças da competência</small></article></div><div class="fv1-risk-stack"><article class="is-${riskTone}"><span>Inadimplência até hoje</span><strong>${k.delinquency==null?'—':percent(k.delinquency)}</strong><small>${money(k.delinquency_value)} vencido agora</small></article><article class="is-danger"><span>Vencido</span><strong>${money(k.overdue)}</strong><small>Cobranças vencidas da competência</small></article></div></section>${chart}`;
